def components(grid, connectivity):
    h, w = len(grid), len(grid[0])
    seen, objects = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            obj = []
            while q:
                y, x = q.popleft()
                obj.append((y, x))
                for dy, dx in connectivity:
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] != 0 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append(obj)
    return objects

def transform(grid):
    eight = [(dy, dx) for dy in (-1, 0, 1) for dx in (-1, 0, 1) if dy or dx]
    four = [(1, 0), (-1, 0), (0, 1), (0, -1)]
    objs = components(grid, eight)
    def four_count(obj):
        pts = set(obj)
        seen = set()
        n = 0
        for p in obj:
            if p in seen:
                continue
            n += 1
            q = [p]; seen.add(p)
            while q:
                y, x = q.pop()
                for dy, dx in four:
                    v = (y + dy, x + dx)
                    if v in pts and v not in seen:
                        seen.add(v); q.append(v)
